def kth(arr, k):
    if not arr:
        raise ValueError("Array must contain at least one element")
    if k < 0 or k >= len(arr):
        raise IndexError("k is out of bounds")

    pivot = arr[0]
    less = [x for x in arr if x < pivot]
    equal = [x for x in arr if x == pivot]
    greater = [x for x in arr if x > pivot]

    if k < len(less):
        return kth(less, k)
    elif k < len(less) + len(equal):
        return pivot
    else:
        return kth(greater, k - len(less) - len(equal))


print(kth([1, 2, 3, 4, 5, 6, 7], 4))
print(kth([3, 6, 7, 1, 6, 3, 8, 9], 5))
print(kth([3, 6, 7, 1, 6, 3, 8, 9], 2))
